"""One offline documentation source for the Help Center and distributable manuals."""
import json,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
topics=[]
def topic(id,title,summary,steps,advanced,example):topics.append(dict(id=id,title=title,summary=summary,steps=steps,advanced=advanced,example=example))
topic('start','Your first five minutes','Browse saved evidence first. No programming, subscription or new import is needed.',[
 'Open the verified DRAGONHYDRA shortcut. A one-use login exchange opens your local dashboard. If a session expires, reopen it from the launcher.',
 'Read Overview: check the count, the datastore that supplied it and the time of that read. Counts are observations, not unique football matches.',
 'Open Football research. Search a team such as Arsenal, then open a result. Read the source, provenance, date and any recorded bookmaker prices.',
 'To calculate statistics, choose a compatible series in the guided selection box. Use full series sets its source, series, provenance and unit for you.',
 'Use Help or F1 anywhere. Beginner Mode adds guidance; switching it off does not remove records or disable features.'
], 'Preferences are stored in this workspace’s SQLite control database. They contain only Beginner Mode and tour completion, not secrets. Help is bundled locally; external documentation links need internet. The previous beta.4 checkpoint contained 5,840 observations: 2,282 COLLECTED, 3,474 IMPORTED and 84 SYNTHETIC. Current counts are queried, not hard-coded.', 'Try Football research → Arsenal → Search matches → Inspect result. A missing odds panel means no safely linked quotations were found, not zero probability.')
topic('overview','Overview','Find out what is stored, where it was read from and whether the application can use it.',[
 'Retained observations counts records in the selected datastore. One match can have a result and several odds quotations; separately attributed imports remain separate evidence.',
 'Read the data-source banner. PostgreSQL and SQLite offline are different datastores. Offline connection mode only disables external APIs; it does not prevent local PostgreSQL queries.',
 'Use Test PostgreSQL connection for a genuine read-only version and identity query. Refresh re-reads data; it does not collect from football APIs.',
 'Use the provenance cards to distinguish imported, collected and synthetic evidence. Recent activity describes actual local operations.'
], 'PostgreSQL CONNECTED means a read-only transaction succeeded in this application session. NOT_CHECKED means no query has run yet. Last success is a timestamp, not a permanent guarantee. A failed read displays Unavailable, never a misleading zero or an automatic SQLite fallback. PostgreSQL “Query OK” is not a full physical database corruption audit.', '5,840 observations plus PostgreSQL CONNECTED means that count was returned by a real PostgreSQL query at the displayed read time.')
topic('football-research','Football research','Search saved match results and inspect safely linked bookmaker prices in plain English.',[
 'Enter a team, competition or season, or leave search blank. Select a source and provenance if you want to narrow the results.',
 'Dates restrict the match calendar date, where supplied. Unknown dates are kept unknown. Search matches applies your selection; Previous and Next move through pages.',
 'Open a result to see the original source fields, collection time and evidence hash. A missing score is shown as Not supplied, never guessed.',
 'Open Recorded odds to view bookmaker, market, outcome, decimal price and known quote time. Inspect quote shows the underlying observation.',
 'Read the probability explanation: decimal odds 2.50 imply 100 ÷ 2.50 = 40%. This includes bookmaker margin and is not a calibrated prediction or a promise of profit.'
], 'Search scans at most 10,000 selected observations and returns at most 50 matches per page. Larger datasets require a source filter rather than silent truncation. Links require a match ID within the same source, or a complete exact source/competition/season/teams/date identity. Sources are not merged by similar names. Quotes without enough identity remain available in Sports odds and Historical observations.', 'Search Arsenal in the historical football source. A 1–0 result and a saved 1X2 quotation describe different records with different provenance clocks.')
topic('history','Historical observations','Browse the original saved records and inspect their provenance.',[
 'Choose Source (where data came from), Kind (what type it is), Provenance (how it was acquired), Series (one measurement) and Unit (how it is measured). All means no restriction.',
 'Search evidence looks through stored record content, including team names and metadata. Apply updates the table. Clear filters removes restrictions.',
 'Collection time range uses UTC retrieval time, not the date a match was played. Use Football research for match-date searches.',
 'Inspect opens the exact evidence, original fields, hash and validation warnings. Close or Escape returns to the table.',
 'Export CSV and Export JSON download the current filter selection. Check the documented 10,000-record export limit; export narrower ranges for larger selections.'
], 'Observations preserve unknown observed_at values. Date-only event fields are not fabricated into midnight timestamps. The table and timeline display one 100-row page; analysis queries the full filtered set up to 10,000 rows. Browser downloads go to your browser’s chosen download folder. CSV formula-like text is escaped for spreadsheet safety.', 'Filter IMPORTED + SPORTS_RESULT, search Chelsea and click Apply. Clear filters if “No records match” appears unexpectedly.')
topic('sports','Sports odds','Explore retained bookmaker quotations and understand implied probabilities.',[
 'Select an odds source and IMPORTED or COLLECTED provenance. SYNTHETIC contains fictional demonstration prices.',
 'Choose one odds series and its decimal unit before analyzing prices. A home-win price and a draw price are different series.',
 'Enter decimal odds greater than 1 and press Calculate implied probability. The calculation uses your entered price; it does not fetch a current bookmaker offer.',
 'View historical results changes the table’s record category. Clear filters if a previously selected odds series hides match results.'
], 'Probability is 1/decimal odds, reported as a fraction or percentage. Market probabilities can sum above 100% because of bookmaker margin. A recorded quotation is not necessarily executable, simultaneous with another quote or current. Unknown quote time stays unknown. Numerical summaries of prices are not betting forecasts.', 'Decimal odds 2.00 imply 50%; 4.00 imply 25%. These arithmetic conversions do not establish the real chance of a result.')
topic('numerical','Numerical intelligence','Summarize compatible numbers with reproducible calculations.',[
 'Pick a ready-to-analyze series from the guided list and press Use full series, or select source, series, provenance and unit manually.',
 'Apply loads the matching records. Analyze selected series calculates statistics only after the selection is compatible. An incomplete selection opens helpful guidance without a red error.',
 'Count is how many numerical records were used. Mean is the average. Median is the middle value. Minimum and maximum show the range; sample spread describes variation.',
 'Moving average window is a number of records, not days. Inputs, method and uncertainty shows IDs, exact values, algorithm version, fingerprint and limitations.',
 'Advanced users can compare two exact-time series or evaluate previously recorded binary predictions. Read the matching requirements before interpreting these results.'
], 'Each calculation requires one source × series × unit × provenance. Zero or multiple compatible scopes are rejected on the server even if a client is bypassed. Maximum 10,000 rows, window 1–1,000. Pearson correlation needs at least three unique pairs at exact known observation times and nonconstant series. Date-only records cannot establish exact-time correlation. The approximate confidence interval assumes independent samples; outlier flags are review candidates. Brier score/log loss require paired probabilities and 0/1 outcomes and do not verify prediction chronology.', 'Choose football.total_goals with the goals unit and IMPORTED provenance. Do not combine total goals with decimal odds or synthetic prices.')
topic('sources','Data sources and CSV imports','Import permitted files without writing JSON for ordinary CSV work.',[
 'Use Import Data, choose CSV, then Preview. Confirm the filename, detected encoding, delimiter and visible rows.',
 'Select an existing source or Create source for this file. A source is the name under which the imported evidence will remain traceable.',
 'Choose the schema profile and map columns with dropdowns. Confirm date format, decimal convention and units. Unknown times must remain unknown.',
 'Validate, review rejected rows and warnings, then Confirm import. Follow progress and inspect the receipt’s inserted, duplicate and rejected counts.',
 'Open imported observations or Analyze imported values. Re-importing the same records should report duplicates, not create extra observations.'
], 'Upload limit is 20 MiB; CSV/TSV, JSON, JSONL, XLSX, structured XML, supported HTML tables, text PDF and read-only SQLite are supported through their configured readers. PDF text extraction is not OCR. Source ID is a stable internal name; Display name is a friendly label. Configured file/location, field mapping JSON and reader options are advanced controls. HTTP collection requires explicit permission and connected mode. Invalid atomic batches commit no observations. Edit loads existing settings; enable/schedule can start approved background collection; disabling stops future scheduling without deleting historical data.', 'For a football CSV map Date, Home team, Away team, Home goals and Away goals. “0 inserted, 3040 duplicates” means those records were already retained.')
topic('football','Football API Control Center','Configure six independent providers. A configured card is not proof of a connection.',[
 'Choose Offline for local research or Configured connections for explicitly enabled providers. No subscription is activated automatically.',
 'Save the provider configuration, enter its own API key when required and Save / replace API key. Saved keys are masked and never sent back to the browser.',
 'Test authentication or Test connection / discover competitions. Read the actual result and quota. Choose a supported competition, season and data category.',
 'Collect now performs one approved acquisition. View import results shows the real receipt. Enable scheduled collection only if you want recurring requests.',
 'Remove configuration disables that provider without deleting historical observations. Remove saved API key removes the local secret; revoke it at the provider if needed.'
], 'The six identities are APIfootball.com, API-Football/API-Sports, TheSportsDB, Highlightly, football-data.org and OpenLigaDB. They have distinct protocols, budgets and credentials. Anonymous/public-demo providers do not need invented private keys. Local budget counters are not total account usage. HTTP 401/403 may mean invalid credentials or missing feature permission; 429 means stop until retry allowance. Free-plan availability and odds access are provider-controlled. LIVE_PASS means real endpoint acceptance; MOCK_PASS only means isolated protocol regression passed.', 'Start with the provider already configured by the owner. Test first, choose a supported historical season, collect once, then inspect the receipt.')
topic('football-comparison','Football Data Comparison','Review agreement, missing information and conflicts without merging original records.',[
 'Filter by source, competition, season, team, dates and category; press Compare retained sources.',
 'Open each source record to compare identities, dates, score period and values. SINGLE_SOURCE is not corroboration.',
 'AGREEMENT_CANDIDATE means matching candidate records agree. CONFLICT_REQUIRES_REVIEW means their recorded values differ.',
 'Only use Explicit identity aliases when you have independently confirmed that two names refer to the same entity.'
], 'Aliases preserve originals and provide an owner-confirmed comparison mapping. Similar names alone are not identity proof. Providers may share upstream data, so agreement does not establish independent truth. Incomplete identities are explicitly listed instead of force-merged.', 'Compare two providers’ Arsenal fixtures on the same date, competition and season, then inspect their source IDs before accepting agreement.')
topic('postgresql','PostgreSQL Control Center','Inspect the real local relational database and its read-only results.',[
 'Test Connection executes a real version and identity query. Discover PostgreSQL only discovers local service/client details; it does not by itself prove a login.',
 'Refresh Databases lists accessible catalog entries. Select Database changes configuration only when safe; credentials are bound to the selected endpoint and database.',
 'View Schemas and Inspect Tables discover real objects. Describe Columns explains types. Browse Sports Records and Run Read-only Query return bounded rows.',
 'View Import Receipts shows retained import evidence. Check MCP compares a real MCP SELECT with an independent driver query.',
 'Create Authorized Backup makes a verified archive. Test Restore in Isolation creates a separate owned schema; it never overwrites the original research schema.'
], 'The current installation uses the authorized dragonhydra_intelligence schema within codex_engineering because existing credentials lack CREATEDB/CREATEROLE. AI reads use codex_mcp_ro; runtime/migration/admin currently share an existing non-superuser owner with separate protected credential bindings. Do not change unrelated roles or databases. Supported SQL is simple SELECT columns FROM owned_table LIMIT n, max 100, with functions, joins, writes and compound statements prohibited. Statement timeout 10 seconds, lock timeout 5 seconds. Use preserved SQLite offline explicitly to change datastore; PostgreSQL failure does not silently fall back. Initialize/migrate/activate are advanced operations requiring verified ownership and reconciliation. SQL Server is not an active runtime dependency.', 'SELECT id,kind,origin FROM observations LIMIT 10 returns ten saved identities. “NOT_CHECKED” asks for a test; “AUTHENTICATION_FAILED” asks you to check the saved authorized login.')
topic('recovery','Recovery Center, backups and restore','Understand task outcomes and preserve recoverable data.',[
 'Queued tasks are waiting; Running tasks show real progress. Open Receipt / details to inspect results.',
 'Failed, Blocked, Interrupted or Cancelled tasks keep their evidence. Correct the reason before Resume; cancellation does not undo already committed records.',
 'Create verified backup uses the selected datastore. For PostgreSQL, inspect and test restore in PostgreSQL Control Center. For SQLite, restore through the native launcher.',
 'Keep old releases and verified backups. Do not restore over original research merely to test a backup.',
 'Revoke browser sessions signs browsers out. Reopen through the launcher to authenticate again.'
], 'PostgreSQL backups use pg_dump plus a repeatable-read snapshot and a SQLite control-state backup; isolated restore compares table counts and original payload fingerprints. Separate-database restore requires privileges not currently available. Saved API/database secrets are deliberately excluded from public archives and backups. DPAPI credentials are bound to the Windows user and data directory; configure authorized credentials again after moving to another user/path. SQLite backup uses the supported backup API, including committed WAL. SQL Server maintenance evidence remains untouched.', 'A cancelled upload can be retried after inspecting its task. A completed duplicate-only import is successful preservation, not data loss.')
topic('cloud','Cloud AI Control Center','Configure optional AI interpretation without automatically sharing a database.',[
 'Choose a supported developer provider and model/deployment. A consumer chat subscription is not necessarily API access.',
 'Save a protected credential, enable the configuration and test connection. Quota or missing credits can block inference even if authentication works.',
 'Choose specific records, load them, then Preview selected data. Review exactly what will leave the computer.',
 'Approve and Send only the intended request. Inspect its returned text, usage and receipt. Stop or inspect a remote task when that provider supports it.'
], 'OpenAI Responses, Claude Messages, xAI, supported Microsoft Foundry/Azure OpenAI/Copilot Studio interfaces, Manus task workflows and compatible local endpoints differ. No purchases or subscriptions are created. Cost may be unknown; local request/output/time limits are not a guaranteed currency cap. Manus tasks may continue remotely until explicitly stopped through supported controls. Cloud interpretations are not database facts. The existing OpenAI live-inference gate was blocked by account credits; mock tests do not establish genuine replies.', 'Select five football records and ask “Summarize only these results and cite source IDs.” Inspect the preview before allowing a cloud request.')
topic('cockpit','AI Intelligence Cockpit and floating chat','Hold provider-specific conversations while browsing evidence.',[
 'Configure a provider and Open chat. Select an available model, write a message and Send. The response must come from that configured provider.',
 'New conversation creates separate history; Search history finds earlier sessions. Changing provider does not transfer a previous conversation’s sharing approval.',
 'Move or resize the floating window, Dock right, Expand, Minimize or Restore. These only change layout.',
 'Inspect cited tools and source records. Stop response stops local waiting/cancels where supported; Retry repeats the failed operation deliberately.',
 'For a roundtable, explicitly select each provider and approve separate requests. Unconfigured companies do not receive messages or produce fake replies.'
], 'Conversations retain company/model/session identity, tool receipts and usage when available. Cloud tools use bounded authenticated application functions, not arbitrary local shell access. Export/copy can include your conversation content; choose recipients carefully. Local inference remains optional. Switching Offline prohibits outbound cloud inference while preserving local research.', 'Ask a connected provider to query a bounded set of stored football results. Inspect the tool receipt instead of trusting an unsupported database count.')
topic('knowledge','Living Search','Search a local index of permitted supporting sources.',[
 'Enter search text and search indexed titles, tags and retrieved content. This is not unrestricted web crawling.',
 'Inspect a source’s title, URL, discovery/refresh date and evidence fingerprint.',
 'Create or edit an approved source with a useful title and tags. Enable retrieval only for that permitted URL.',
 'Refresh on demand, or deliberately enable scheduled refresh. Offline mode still allows searching previously stored knowledge.'
], 'A documentation page supports a capability claim but is not a football observation. URL availability and content fingerprints can change. Models receive only selected bounded knowledge evidence. Registered sources without retrieval are not verified live content.', 'Search “PostgreSQL backup” to find indexed documentation and inspect when it was last retrieved.')
topic('tools','AI evidence tools','Run documented bounded queries without requiring a model response.',[
 'Choose a documented tool, source and row limit. Fill only its supported arguments.',
 'Run selected read-only tool and inspect the returned rows, source IDs and execution receipt.',
 'Use schema descriptions to understand fields before requesting data.'
], 'Read-only templates and identifier allowlists constrain SQL. A tool execution is genuine local computation even when a cloud provider is unconfigured. Returning no rows is distinct from a failed operation.', 'Choose football results and a limit of 10, then inspect the ten returned source records.')
topic('tool-registry','Tool registry and MCP extensions','See exactly which capabilities AI agents can request.',[
 'Select a tool to read its description, permissions and argument fields. Enable or disable only the tools you intend to offer.',
 'Run a bounded read and inspect the receipt. Data-changing requests stage an explicit application action rather than granting a model a shell.',
 'For MCP, configure a separate local credential and inspect actual connection status. A registered connector is not proof that a query succeeded.'
], 'Registry argument schemas reject unknown fields. SQL tools use the independent read-only role, max 100 rows and strict statement grammar. External ChatGPT plugins are not automatically compatible with a standalone application. The local MCP interface requires its own scoped authentication. Secrets are not returned to agents.', 'Use get_postgresql_status or run_bounded_postgresql_select and inspect the execution result before discussing it with a model.')
topic('engineering','Codex engineering','Attach the existing authorized engineering session and inspect its work.',[
 'Connect to the existing local Codex thread for this project. The application does not start a competing worker.',
 'Submit a bounded diagnostic only within the owner’s authorized project. Read its job status and saved result receipt.',
 'Inspect the current checkpoint, modified files, processes and test evidence where available. Reconnect after interruption.'
], 'Codex connection needs its existing supported local App Server interface, workspace and thread. Cloud chat does not receive arbitrary shell authority. A missing local worker is a configuration/access limit, not a completed engineering task. Recovery reuses an existing job ID and receipt rather than blindly replaying work.', 'Request “Read the latest acceptance report and summarize the failed checks; do not change code.”')
topic('hardware','Hardware & process monitor','Read real supported computer measurements.',[
 'Refresh to sample CPU, memory, disk and monitored process data.',
 'Read the timestamp and units. Percentages, bytes and temperature are different measurements.',
 'UNAVAILABLE means no reliable sensor or permission exists; it does not mean zero load or zero temperature.'
], 'Windows process/service APIs and available NVIDIA-SMI readings are used without installing kernel drivers. Sampling windows affect CPU readings. Per-process network attribution or CPU temperature may not be available. Only task-owned processes are controlled; unrelated services are preserved.', 'Compare application RAM usage across refreshes, rather than interpreting one idle CPU sample as a performance benchmark.')
topic('diagnostics','System diagnostics','Inspect module health and useful error details.',[
 'Read each module’s state and dependencies. READY means that component initialized, not that every external provider is live-connected.',
 'Open Full status and integration limits for sanitized technical details.',
 'Optional local interpretation needs an explicitly configured loopback endpoint and model. Save configuration, then Explain current filtered evidence if intended.'
], 'Status receipts distinguish datastore reads from cached historical tests. Error messages exclude credentials. SQL Server, unrelated software and Windows services are not changed to clear tests. Report the failed action, timestamp and receipt path when asking for help.', 'If the observation count is Unavailable, test the selected PostgreSQL connection before changing any source settings.')
topic('sentiment','Public text & sentiment','Inspect source-backed text and clearly labeled interpretations.',[
 'Choose retained text records and inspect their source before interpretation.',
 'Interpret retained text runs the built-in method and shows the result for each observation.',
 'Read method limitations rather than treating a label as an observed fact.'
], 'The built-in method is a small English word baseline, not a multilingual trained model. It may abstain on unsupported languages or negation. It does not replace original text or create measured sentiment facts.', 'Inspect a textual observation, then compare the method explanation with the actual words.')
topic('weather','Weather intelligence','Keep actual measurements separate from forecasts.',[
 'Measurements selects weather observations. Forecasts selects predictions.',
 'Inspect geography, unit, observation time, forecast issue time and valid time.',
 'Use one compatible series for a chart or analysis; never mix cities, units or measurement and forecast classes without an explicit method.'
], 'Observation time, issue time, valid time and retrieval time are different clocks. Unknown values remain missing. A forecast becoming older does not make it an observed measurement.', 'A forecast issued Monday for Wednesday is not a Wednesday weather observation.')
topic('launcher','Windows launcher and safe shutdown','Open the authenticated application and preserve your workspace.',[
 'Start / open dashboard starts or reuses the service for the selected data directory, then opens a one-use authenticated browser session.',
 'Choose Offline or Configured connections. Find free port sets port 0; the launcher chooses a free port without stopping another application.',
 'System health, Data sources, Active tasks and Diagnostics open those dashboard pages. Selected database displays the actual selected datastore.',
 'Create verified backup uses the active datastore. Restore opens the supported isolated PostgreSQL workflow or a confirmed SQLite restore with a pre-restore backup.',
 'Stop gracefully ends this workspace’s worker. Closing the launcher alone leaves the service running. Revoke browser sessions logs browsers out.'
], 'The launcher verifies service identity and data directory before reuse. Different versions or databases are never silently hijacked. Installed and portable editions use writable user state by default. Uninstall removes owned application files and keeps user databases/credentials. Earlier release folders remain rollback options. Native pointer automation was unresolved in a prior checkpoint; CLI/browser acceptance is recorded separately rather than substituting it for clicks.', 'If a port is occupied, choose Find free port. Never stop an unrelated service to claim the port.')
topic('troubleshooting','Messages and recovery actions','Read what the application actually knows before retrying.',[
 'No data found: clear filters or choose a source with observations. Empty is not a database failure.',
 'Choose one compatible series: use the guided source/series/unit/provenance selection, then analyze again.',
 'NOT_CHECKED: no query has run this session. CONNECTED: a real query succeeded at the shown time. FAILED or AUTHENTICATION_FAILED: inspect the reason and test again after correcting it.',
 'OFFLINE: external requests are disabled; saved records and local database functions still work. CONFIGURED: settings exist, but connection success is not established.',
 'RATE_LIMITED: wait until the provider’s retry time. BLOCKED: the required permission, configuration or access is missing. UNAVAILABLE: a measurement or service could not be obtained.',
 '0 inserted with duplicates: matching observations were already retained. Invalid atomic batch: no partial observation set was committed.'
], 'PASS describes executed acceptance; LIVE_PASS means a genuine external/database result; MOCK_PASS identifies simulated provider protocol tests; NOT_RUN was not executed; PARTIAL has unresolved gates; FAIL has actual failed evidence. PENDING/QUEUED/RUNNING are task progress states; COMPLETE has a committed receipt; INTERRUPTED requires recovery review. Authentication required means reopen through the launcher, never disable security.', 'If authentication works but an AI reply reports insufficient quota, usable account credits may be missing. Repeated retries do not fix billing access.')
glossary={
 'Observation':'One retained measurement or record; not necessarily a unique match.', 'Source':'The independently identified origin of a record.', 'Series':'One measurement definition, such as total goals or one bookmaker market/outcome.', 'Unit':'The measurement scale, such as goals, decimal odds or degrees Celsius. Unknown is an explicit missing unit, not an invented one.',
 'Provenance':'How a record originated and which source/evidence supports it.', 'IMPORTED':'Brought into the application from a file or historical dataset.', 'COLLECTED':'Acquired through a collection process; not automatically live or current.', 'SYNTHETIC':'Fictional demonstration or test data. Never treat it as measured football evidence.', 'INFERRED':'Derived or predicted information, not a directly observed fact.', 'VERIFIED':'Passed the specifically documented check; it does not prove every source claim true.', 'UNCERTAIN':'Evidence or interpretation has unresolved limitations.', 'INVALID':'Failed a stated validation rule.',
 'SPORTS_RESULT':'A saved sports result or result-related measurement; inspect the original score and status.', 'SPORTS_ODDS':'A retained bookmaker quotation.', 'FOOTBALL_RECORD':'A structured football entity such as a competition, team, fixture or standing; not necessarily numerical.', 'NUMBER':'A numerical measurement whose meaning is defined by its series and unit.', 'PRICE':'A price measurement in its stated unit.', 'SHORT_TEXT':'Source-backed text.', 'WEATHER_OBSERVATION':'An actual weather measurement.', 'WEATHER_FORECAST':'A prediction with separate issue and validity times.',
 'Mean':'Arithmetic average: sum divided by count.', 'Median':'Middle value after sorting.', 'Standard deviation':'A measure of how spread out numerical values are.', 'Outlier':'A value flagged for review; not automatically an error.', 'Correlation':'A mathematical association, not proof that one variable caused another.', 'Confidence interval':'A method-dependent uncertainty range whose assumptions must hold.', 'Decimal odds':'Bookmaker price including stake in the gross return; historical prices are not current offers.', 'Implied probability':'100 divided by decimal odds, as a percent; bookmaker margin remains.',
 'Observed time':'When the source says a measurement was observed.', 'Collection time':'When DRAGONHYDRA retrieved or imported it.', 'Date only':'Calendar date without reliable time-of-day or timezone. No midnight is invented.', 'Fingerprint / SHA-256':'A content identifier used to detect changes; not proof that source content is true.', 'Duplicate':'A record identity already retained; its original evidence stays unchanged.', 'Receipt':'The recorded outcome of an import, query, calculation or tool action.',
 'PostgreSQL':'The selected relational database platform; requires an authorized local connection.', 'SQLite offline':'An explicitly selected local datastore and the application control-state store.', 'Schema':'A named collection of database tables with defined ownership.', 'Read-only':'Queries may read authorized data but cannot change it.', 'MCP':'A protocol for invoking defined tools; registration alone is not connection acceptance.', 'DPAPI':'Windows user-scoped protection for saved credentials. Moving encrypted files to another user/path may require re-entry.', 'CSRF':'Session protection against unrelated sites triggering changes through your browser.'}
data={'version':'0.2.0-beta.5','topics':topics,'glossary':glossary,'limits':{'upload_mib':20,'analysis_rows':10000,'research_rows':10000,'query_rows':100,'history_page':100}}
(ROOT/'application/living/web/help.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf-8')
docs=ROOT/'docs/mission-006';docs.mkdir(exist_ok=True)
for advanced,name in [(False,'BEGINNER-GUIDE.md'),(True,'ADVANCED-GUIDE.md')]:
 lines=['# DRAGONHYDRA '+data['version']+' · '+('Advanced reference' if advanced else 'Beginner guide'),'','Available offline. Original evidence remains distinct from predictions and AI interpretation.','']
 for t in topics:
  lines+=['## '+t['title'],'',t['summary'],'']
  lines+=([t['advanced'],''] if advanced else [*(str(i+1)+'. '+s for i,s in enumerate(t['steps'])),'','Example: '+t['example'],''])
 lines+=['## Glossary','',*('**'+k+'** — '+v+'\n' for k,v in glossary.items())]
 (docs/name).write_text('\n'.join(lines),encoding='utf-8')
body=''.join('<section id="'+t['id']+'"><h2>'+html.escape(t['title'])+'</h2><p>'+html.escape(t['summary'])+'</p><ol>'+''.join('<li>'+html.escape(s)+'</li>' for s in t['steps'])+'</ol><p><b>Example:</b> '+html.escape(t['example'])+'</p><details><summary>Advanced reference</summary><p>'+html.escape(t['advanced'])+'</p></details></section>' for t in topics)
(docs/'USER-MANUAL.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>DRAGONHYDRA offline manual</title><style>body{font:18px/1.7 system-ui;max-width:1000px;margin:40px auto;padding:20px;color:#182b33}a{color:#145b78}section{border-top:1px solid #ddd;padding:20px 0}li{margin:10px 0}</style><h1>DRAGONHYDRA '+data['version']+' · Offline user manual</h1><p>Beginner workflows and advanced reference. No network, account or application service is needed to read this file.</p><nav>'+''.join('<a href="#'+t['id']+'">'+html.escape(t['title'])+'</a> · ' for t in topics)+'</nav>'+body+'<h2>Glossary</h2><dl>'+''.join('<dt><b>'+html.escape(k)+'</b></dt><dd>'+html.escape(v)+'</dd>' for k,v in glossary.items())+'</dl></html>',encoding='utf-8')
print(json.dumps({'topics':len(topics),'glossary':len(glossary),'offline_manuals':3}))
